import json

def extract_json_values(message: str) -> dict:
    """
    Extracts values associated with 'key1' and 'key2' from a JSON string.

    Args:
        message: A string which may represent a JSON object.

    Returns:
        A dictionary containing the values of 'key1' and 'key2' if they exist,
        or an empty dictionary if the input is not a valid JSON object.
    """
    try:
        json_object = json.loads(message)
        result = {}
        if 'key1' in json_object:
            result['key1'] = json_object['key1']
        if 'key2' in json_object:
            result['key2'] = json_object['key2']
        return result
    except json.JSONDecodeError:
        return {}
