import functools
import math

@functools.lru_cache(maxsize=None)
def fibonacci(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci(n-1) + fibonacci(n-2)

def main():
    try:
        n = float(input())
        n = math.floor(n)

        if n < 0:
            sign = (-1)**(abs(n)+1)
            result = sign * fibonacci(abs(n))
        else:
            result = fibonacci(n)

        print(result)
    except ValueError:
        print("Invalid input. Please enter a number.")

if __name__ == "__main__":
    main()
