def solve():
    n, m = map(int, input().split())
    edges = []
    for _ in range(m):
        a, b, c = map(int, input().split())
        edges.append((a, b, c))

    def is_reachable(repaired_roads):
        adj = [[] for _ in range(n + 1)]
        for i in range(m):
            a, b, c = edges[i]
            if c == 0 or i + 1 in repaired_roads:
                adj[a].append(b)

        visited = [False] * (n + 1)
        q = [1]
        visited[1] = True

        while q:
            u = q.pop(0)
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    q.append(v)

        for i in range(1, n + 1):
            if not visited[i]:
                return False
        return True


    min_repaired = float('inf')
    best_repaired_roads = []

    for i in range(1 << m):
        repaired_roads = []
        for j in range(m):
            if (i >> j) & 1:
                repaired_roads.append(j + 1)

        if is_reachable(repaired_roads):
            if len(repaired_roads) < min_repaired:
                min_repaired = len(repaired_roads)
                best_repaired_roads = repaired_roads

    if min_repaired == float('inf'):
        print("-1")
    else:
        print(min_repaired)
        print(*best_repaired_roads)

