def get_twenty_primes():
    """
    Returns a list of the first twenty prime numbers less than 50.
    """
    primes = []
    num = 2
    while len(primes) < 20 and num < 50:
        if is_prime(num):
            primes.append(num)
        num += 1
    return primes

def is_prime(n):
    """
    Checks if a number is prime.
    """
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True
